<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue';
import {NAlert,NButton,NCard} from 'naive-ui';
import {api,ApiError,errorMessage} from '../../shared/api';
const props=defineProps<{workspaceId:string}>(),emit=defineEmits<{sessionExpired:[]}>();
type Observation={runtime:{status?:string;service?:string;configuration?:{state:'initializing'|'ready'|'stale';lastValidatedAt:number|null;error:string|null;moduleRevisions:Record<string,string>|null};counts?:{tasks:number;conversations:number}};execution:{status:string;runtimeId?:string;hostId?:string}|null};
const observation=ref<Observation|null>(null),loading=ref(false),error=ref('');let controller:AbortController|undefined;
async function load(){controller?.abort();const c=new AbortController();controller=c;loading.value=true;error.value='';observation.value=null;try{const r=await api<Observation>(`/workspaces/${encodeURIComponent(props.workspaceId)}/runtime-monitor`,c.signal);if(controller===c&&!c.signal.aborted)observation.value=r;}catch(e){if(controller===c&&!c.signal.aborted){error.value=errorMessage(e);if(e instanceof ApiError&&e.status===401)emit('sessionExpired');}}finally{if(controller===c)loading.value=false;}}
watch(()=>props.workspaceId,()=>void load(),{immediate:true});onUnmounted(()=>controller?.abort());
</script>
<template><section class="system-status"><div class="status-heading"><h2>服务状态</h2><NButton :loading="loading" :disabled="loading" @click="load">刷新状态</NButton></div><p v-if="loading" role="status">正在获取服务状态…</p><NAlert v-else-if="error" type="error" role="alert">暂时无法获取服务状态。{{error}}<NButton @click="load">重试</NButton></NAlert><div v-else-if="observation" class="service-grid"><NCard size="small"><h3>交互与任务</h3><p>{{observation.runtime.status==='unavailable'?'暂时无法连接':observation.runtime.configuration?.state==='ready'?'配置已同步':'尚未就绪'}}</p><details v-if="observation.runtime.configuration"><summary>运行详情</summary><p v-if="observation.runtime.configuration.error">最近更新未完成，请稍后刷新。</p><p v-for="(revision,name) in observation.runtime.configuration.moduleRevisions??{}" :key="name">{{name}} · {{revision}}</p><p v-if="observation.runtime.configuration.lastValidatedAt">更新于 {{new Date(observation.runtime.configuration.lastValidatedAt).toLocaleString('zh-CN')}}</p></details></NCard><NCard size="small"><h3>执行服务</h3><p>{{!observation.execution?'尚未配置监控':observation.execution.status==='reachable'?'进程可达':'暂时无法连接'}}</p><details v-if="observation.execution?.status==='reachable'"><summary>运行详情</summary><p>{{observation.execution.runtimeId}}</p><p>{{observation.execution.hostId}}</p></details></NCard></div></section></template>
<style scoped>.system-status{display:grid;gap:1rem;margin-bottom:1.5rem}.status-heading{display:flex;gap:1rem;align-items:center;justify-content:space-between}.status-heading h2{margin:0}.service-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.service-grid h3{margin:0}.service-grid p{overflow-wrap:anywhere}.service-grid details{font-size:.875rem;color:var(--muted)}@media(max-width:47.5rem){.service-grid{grid-template-columns:1fr}}</style>
